#!/usr/bin/env bash
# Login-node-safe CTest handling.
#
# Purpose:
#   Execute a restricted subset of CTest cases considered safe for execution on
#   a JACI login node. This avoids running large MPI tests directly on the login
#   environment.
#
# Requires:
#   A completed build tree generated by configure and build.
#
# Produces:
#   ${MONAN_JEDI_LOG_ROOT}/07_ctest.log
#
# Expected result:
#   ctest exits with status zero and the selected tests pass.

monan_jedi_test_login() {
  # Recreate the same stack environment used by configure and build.
  monan_jedi_load_stack
  require_cmd ctest

  # Restrict login-node tests by default to avoid launching large MPI workloads
  # outside PBS compute nodes.
  local login_safe_regex="${MONAN_JEDI_CTEST_REGEX:-^mpasjedi_coding_norms$}"

  if [[ ! -f "${MONAN_JEDI_BUILD_DIR}/CTestTestfile.cmake" ]]; then
    log_error "Build tree does not contain CTestTestfile.cmake: ${MONAN_JEDI_BUILD_DIR}"
    exit 1
  fi

  cd "${MONAN_JEDI_BUILD_DIR}" || {
    log_error "Failed to enter build directory: ${MONAN_JEDI_BUILD_DIR}"
    exit 1
  }

  ctest --output-on-failure \
    -j "${MONAN_JEDI_CTEST_JOBS}" \
    -R "${login_safe_regex}" \
    2>&1 | tee "${MONAN_JEDI_LOG_ROOT}/07_ctest.log"
}
